operation.add:
// Odoo Integration Menu
$odoo = array();

if ($this->user->hasPermission('access', 'extension/module/odoo_connector')) {
	$odoo[] = array(
		'name'	   => $this->language->get('text_odoo_settings'),
		'href'     => $this->url->link('extension/module/odoo_connector', 'user_token=' . $this->session->data['user_token'], true),
		'children' => array()
	);
}

if ($this->user->hasPermission('access', 'extension/module/odoo_product_mapping')) {
	$odoo[] = array(
		'name'	   => $this->language->get('text_odoo_product_mapping'),
		'href'     => $this->url->link('extension/module/odoo_product_mapping', 'user_token=' . $this->session->data['user_token'], true),
		'children' => array()
	);
}

if ($this->user->hasPermission('access', 'extension/module/odoo_price_mapping')) {
	$odoo[] = array(
		'name'	   => $this->language->get('text_odoo_price_mapping'),
		'href'     => $this->url->link('extension/module/odoo_price_mapping', 'user_token=' . $this->session->data['user_token'], true),
		'children' => array()
	);
}

if ($this->user->hasPermission('access', 'extension/module/odoo_order_mapping')) {
	$odoo[] = array(
		'name'	   => $this->language->get('text_odoo_order_mapping'),
		'href'     => $this->url->link('extension/module/odoo_order_mapping', 'user_token=' . $this->session->data['user_token'], true),
		'children' => array()
	);
}

if ($this->user->hasPermission('access', 'extension/module/odoo_attribute_mapping')) {
	$odoo[] = array(
		'name'	   => $this->language->get('text_odoo_attribute_mapping'),
		'href'     => $this->url->link('extension/module/odoo_attribute_mapping', 'user_token=' . $this->session->data['user_token'], true),
		'children' => array()
	);
}

if ($this->user->hasPermission('access', 'extension/module/odoo_attribute_value_mapping')) {
	$odoo[] = array(
		'name'	   => $this->language->get('text_odoo_attribute_value_mapping'),
		'href'     => $this->url->link('extension/module/odoo_attribute_value_mapping', 'user_token=' . $this->session->data['user_token'], true),
		'children' => array()
	);
}

if ($odoo) {
	$data['menus'][] = array(
		'id'       => 'menu-odoo',
		'icon'	   => 'fa-cloud-upload',
		'name'	   => $this->language->get('text_odoo'),
		'href'     => '',
		'children' => $odoo
	);
}

// Odoo Integration
$_['text_odoo']                          = 'Odoo Integration';
$_['text_odoo_settings']                 = 'Settings';
$_['text_odoo_product_mapping']          = 'Product Mapping';
$_['text_odoo_price_mapping']            = 'Price Mapping';
$_['text_odoo_order_mapping']            = 'Order Mapping';
$_['text_odoo_attribute_mapping']        = 'Attribute Mapping';
$_['text_odoo_attribute_value_mapping']  = 'Size Code Mapping';

